"""C++ source templates for the generated map-n-flag library.

Kept out of build.py because they are full of C macro bodies; token
placeholders (@@NAME@@) are substituted rather than str.format(), so no brace
escaping is needed.
"""

HEADER_TEMPLATE = r'''/*
 * map-n-flag -- ISO 3166-1 country flags, map silhouettes and the ASL
 * fingerspelling alphabet baked into flash.
 *
 * Generated by tools/build.py. Regenerate with `python tools/build.py`.
 *
 * Build configuration:
 *   scope      : @@SCOPE@@
 *   countries  : @@N_COUNTRIES@@  (flags: @@N_FLAGS@@, maps: @@N_MAPS@@)
 *   states     : @@N_STATES@@  (flags: @@N_STATE_FLAGS@@, maps: @@N_STATE_MAPS@@)
 *   ASL hands  : @@N_SIGNS@@
 *   flag size  : @@FLAG_W@@x@@FLAG_H@@, 4-bit indexed (16-colour palette)
 *   map size   : fit inside @@MAP_BOX@@x@@MAP_BOX@@, 4-bit indexed alpha ramp
 *   hand size  : fit inside @@SIGN_W@@x@@SIGN_H@@, 4-bit indexed alpha ramp
 *
 * Flash footprint:
 *   country flags @@FLAG_KIB@@ KiB + maps @@MAP_KIB@@ KiB = @@TOTAL_KIB@@ KiB
 *   state   flags @@STATE_FLAG_KIB@@ KiB + maps @@STATE_MAP_KIB@@ KiB = @@STATE_TOTAL_KIB@@ KiB
 *   ASL hands     @@SIGN_KIB@@ KiB
 *   RAM cost: 0 bytes. Everything is const and lives in .rodata.
 *
 * This core header has NO dependencies beyond stdint/stddef -- it does not
 * require LVGL. To use the images with LVGL, additionally include
 * "map_n_flag_lvgl.h", which adapts them to lv_img_dsc_t / lv_image_dsc_t.
 *
 * Artwork credits:
 *   Country flags -- lipis/flag-icons, MIT License.
 *   State flags   -- fonttools/region-flags, public domain (Wikipedia).
 *   State maps    -- Natural Earth, public domain.
 *   ASL hands     -- WPClipart via Wikimedia Commons, public domain (CC0).
 */
#ifndef MAP_N_FLAG_H
#define MAP_N_FLAG_H

#include <stdint.h>
#include <stddef.h>
#ifndef __cplusplus
#  include <stdbool.h>
#endif

#ifdef __cplusplus
extern "C" {
#endif

/* ------------------------------------------------------------------------
 * Image format
 *
 * Every image is 4-bit indexed (I4). The data blob is:
 *
 *   [16 palette entries x 4 bytes: B, G, R, A][4bpp pixel rows]
 *
 * Rows are padded up to a whole byte, and the LEFTMOST pixel of each pair is
 * the HIGH nibble. This is byte-for-byte what LVGL v8 and v9 expect, so the
 * same blob feeds LVGL or your own blitter with no conversion.
 *
 * Flags use a per-image 16-colour palette. Maps use a 16-step alpha ramp of a
 * single ink colour, which behaves like a 4-bit alpha mask.
 * ---------------------------------------------------------------------- */

#define MNF_PALETTE_ENTRIES  16
#define MNF_PALETTE_BYTES    (MNF_PALETTE_ENTRIES * 4)

/** Bytes per pixel row, excluding the palette. */
#define MNF_STRIDE(w)        (((w) + 1) / 2)

/** Total blob size for a w*h image, including the palette. */
#define MNF_DATA_SIZE(w, h)  (MNF_PALETTE_BYTES + MNF_STRIDE(w) * (h))

/** One image: dimensions plus a pointer to the palette+pixel blob. */
typedef struct {
    uint16_t w;
    uint16_t h;
    const uint8_t *data;
} mnf_img_t;

/** One country: ISO code, display name, and its two images. */
typedef struct {
    const char *iso2;         /**< Upper-case ISO 3166-1 alpha-2, NUL-terminated. */
    const char *name;         /**< ASCII display name, e.g. "France". */
    const mnf_img_t *flag;    /**< Flag, or NULL if not generated. */
    const mnf_img_t *map;     /**< Outline, or NULL if not generated. */
} mnf_country_t;

/** One US state: abbreviation, display name, and its two images.
 *  Layout-compatible with mnf_country_t; aliased as mnf_state_t for clarity. */
typedef mnf_country_t mnf_state_t;

/** One letter of the ASL manual alphabet and the hand that spells it. */
typedef struct {
    char letter;            /**< Upper-case 'A'..'Z'. */
    uint8_t moves;          /**< 1 if the sign is traced in the air (J, Z). */
    const mnf_img_t *img;   /**< Hand, or NULL if not generated. */
} mnf_sign_t;

/* ------------------------------------------------------------------------
 * Country lookup (unchanged)
 * ---------------------------------------------------------------------- */

/** Number of countries in the table. */
size_t mnf_count(void);

/** Country at index [0, mnf_count()), sorted by ISO code. NULL if out of range. */
const mnf_country_t *mnf_at(size_t index);

/** Look up by ISO code, case-insensitive ("FR" or "fr"). NULL if unknown. */
const mnf_country_t *mnf_find(const char *iso2);

/** Flag image for an ISO code, or NULL if unknown / not generated. */
const mnf_img_t *mnf_flag(const char *iso2);

/** Map outline for an ISO code, or NULL if unknown / not generated. */
const mnf_img_t *mnf_map(const char *iso2);

/** Display name for an ISO code, or NULL if unknown. */
const char *mnf_name(const char *iso2);

/** True if the country has BOTH a flag and a map (for paired game modes). */
bool mnf_has_both(const char *iso2);

/* ------------------------------------------------------------------------
 * US state lookup
 *
 * Parallel API keyed by 2-letter USPS abbreviation ("CA", "TX", "NY").
 * Returns NULL/0/false when GENERATE_STATES was off at build time.
 * ---------------------------------------------------------------------- */

#define MNF_HAS_STATES  @@HAS_STATES@@

/** Number of US states (+ DC) in the table. 0 if states were not generated. */
size_t mnf_state_count(void);

/** State at index [0, mnf_state_count()), sorted by abbreviation. */
const mnf_state_t *mnf_state_at(size_t index);

/** Look up by abbreviation, case-insensitive ("CA" or "ca"). */
const mnf_state_t *mnf_state_find(const char *st);

/** State flag for an abbreviation, or NULL. */
const mnf_img_t *mnf_state_flag(const char *st);

/** State outline for an abbreviation, or NULL. */
const mnf_img_t *mnf_state_map(const char *st);

/** State display name ("California"), or NULL. */
const char *mnf_state_name(const char *st);

/** True if the state has BOTH a flag and a map. */
bool mnf_state_has_both(const char *st);

/* ------------------------------------------------------------------------
 * ASL fingerspelling
 *
 * The 26 hands of the American Sign Language manual alphabet, A to Z, drawn
 * as the signer sees their own right hand. Each is black line art on a
 * transparent page, stored as an alpha ramp like the map outlines, so
 * mnf_row_rgb565_tint() recolours one to any ink. J and Z are motions; their
 * drawings carry the motion as an arrow.
 *
 * Returns NULL/0 when GENERATE_SIGNS was off at build time.
 * ---------------------------------------------------------------------- */

#define MNF_HAS_SIGNS  @@HAS_SIGNS@@

/** Number of hands, 26 when generated. */
size_t mnf_sign_count(void);

/** Hand at index [0, mnf_sign_count()); index 0 is 'A'. NULL if out of range. */
const mnf_sign_t *mnf_sign_at(size_t index);

/** Look up by letter, case-insensitive ('A' or 'a'). NULL if not a letter. */
const mnf_sign_t *mnf_sign_find(char letter);

/** Hand image for a letter, or NULL. */
const mnf_img_t *mnf_sign(char letter);

/* ------------------------------------------------------------------------
 * Pixel access -- for drawing without LVGL (TFT_eSPI, LovyanGFX, anything)
 * ---------------------------------------------------------------------- */

/** Palette index (0-15) at (x, y). Returns 0 if out of bounds. */
uint8_t mnf_index_at(const mnf_img_t *img, uint16_t x, uint16_t y);

/** Palette entry as 0xAARRGGBB. */
uint32_t mnf_palette_argb(const mnf_img_t *img, uint8_t index);

/** Pixel at (x, y) as 0xAARRGGBB. Returns 0 (transparent) if out of bounds. */
uint32_t mnf_pixel_argb(const mnf_img_t *img, uint16_t x, uint16_t y);

/**
 * Decode row `y` into `out` as RGB565, compositing over `bg565`.
 * `out` must hold at least img->w uint16_t values.
 *
 * This is the fast path for direct-to-display blitting: decode one row, push
 * it, repeat. Costs img->w * 2 bytes of scratch instead of a full framebuffer.
 */
void mnf_row_rgb565(const mnf_img_t *img, uint16_t y, uint16_t *out, uint16_t bg565);

/**
 * Like mnf_row_rgb565(), but ignores the palette's colour and uses the entry's
 * alpha only, compositing `fg565` over `bg565`. Lets you recolour map
 * silhouettes at runtime without regenerating them.
 */
void mnf_row_rgb565_tint(const mnf_img_t *img, uint16_t y, uint16_t *out,
                         uint16_t bg565, uint16_t fg565);

/** Pack 8-bit RGB into RGB565. */
uint16_t mnf_rgb565(uint8_t r, uint8_t g, uint8_t b);

/* ------------------------------------------------------------------------
 * Generated geometry
 *
 * Maps are cropped to their own bounding box, so MNF_MAP_BOX is the maximum
 * of width and height, not the size of any particular map. Hands are cropped
 * the same way and fit inside MNF_SIGN_WIDTH x MNF_SIGN_HEIGHT. Read img->w /
 * img->h for the real dimensions.
 * ---------------------------------------------------------------------- */
#define MNF_FLAG_WIDTH   @@FLAG_W@@
#define MNF_FLAG_HEIGHT  @@FLAG_H@@
#define MNF_MAP_BOX      @@MAP_BOX@@
#define MNF_SIGN_WIDTH   @@SIGN_W@@
#define MNF_SIGN_HEIGHT  @@SIGN_H@@

/* Attribute applied to the generated byte arrays. Override before including
 * if your platform needs an explicit flash-placement attribute. */
#ifndef MNF_IMG_ATTR
#  define MNF_IMG_ATTR
#endif

/* Used by the generated data files to define each image descriptor.
 * The leading extern declaration gives the const object external linkage in
 * C++, where namespace-scope const is internal by default. */
#define MNF_DEFINE_IMG(sym, W, H, DATA)                                       \
    extern const mnf_img_t sym;                                               \
    const mnf_img_t sym = { (uint16_t)(W), (uint16_t)(H), (DATA) }

#ifdef __cplusplus
}
#endif

#endif /* MAP_N_FLAG_H */
'''


IMPL_SOURCE = r'''/*
 * map-n-flag lookup and pixel access. Hand-written; not generated.
 */
#include "map_n_flag.h"
#include <string.h>
#include <ctype.h>

extern const mnf_country_t mnf_country_table[];
extern const uint16_t mnf_country_count;

extern const mnf_state_t mnf_state_table[];
extern const uint16_t mnf_state_count_val;

extern const mnf_sign_t mnf_sign_table[];
extern const uint16_t mnf_sign_count_val;

/* ------------------------------------------------------------------------
 * Country lookup
 * ---------------------------------------------------------------------- */

size_t mnf_count(void)
{
    return (size_t)mnf_country_count;
}

const mnf_country_t *mnf_at(size_t index)
{
    if (index >= (size_t)mnf_country_count) return NULL;
    return &mnf_country_table[index];
}

const mnf_country_t *mnf_find(const char *iso2)
{
    if (iso2 == NULL || iso2[0] == '\0' || iso2[1] == '\0') return NULL;

    /* The table is sorted by upper-case ISO code. */
    const char key0 = (char)toupper((unsigned char)iso2[0]);
    const char key1 = (char)toupper((unsigned char)iso2[1]);

    int lo = 0;
    int hi = (int)mnf_country_count - 1;
    while (lo <= hi) {
        const int mid = lo + (hi - lo) / 2;
        const char *c = mnf_country_table[mid].iso2;
        int cmp = (c[0] - key0);
        if (cmp == 0) cmp = (c[1] - key1);

        if (cmp == 0) return &mnf_country_table[mid];
        if (cmp < 0)  lo = mid + 1;
        else          hi = mid - 1;
    }
    return NULL;
}

const mnf_img_t *mnf_flag(const char *iso2)
{
    const mnf_country_t *c = mnf_find(iso2);
    return c ? c->flag : NULL;
}

const mnf_img_t *mnf_map(const char *iso2)
{
    const mnf_country_t *c = mnf_find(iso2);
    return c ? c->map : NULL;
}

const char *mnf_name(const char *iso2)
{
    const mnf_country_t *c = mnf_find(iso2);
    return c ? c->name : NULL;
}

bool mnf_has_both(const char *iso2)
{
    const mnf_country_t *c = mnf_find(iso2);
    return c != NULL && c->flag != NULL && c->map != NULL;
}

/* ------------------------------------------------------------------------
 * US state lookup
 * ---------------------------------------------------------------------- */

size_t mnf_state_count(void)
{
    return (size_t)mnf_state_count_val;
}

const mnf_state_t *mnf_state_at(size_t index)
{
    if (index >= (size_t)mnf_state_count_val) return NULL;
    return &mnf_state_table[index];
}

const mnf_state_t *mnf_state_find(const char *st)
{
    if (st == NULL || st[0] == '\0' || st[1] == '\0') return NULL;

    const char key0 = (char)toupper((unsigned char)st[0]);
    const char key1 = (char)toupper((unsigned char)st[1]);

    int lo = 0;
    int hi = (int)mnf_state_count_val - 1;
    while (lo <= hi) {
        const int mid = lo + (hi - lo) / 2;
        const char *c = mnf_state_table[mid].iso2;
        int cmp = (c[0] - key0);
        if (cmp == 0) cmp = (c[1] - key1);

        if (cmp == 0) return &mnf_state_table[mid];
        if (cmp < 0)  lo = mid + 1;
        else          hi = mid - 1;
    }
    return NULL;
}

const mnf_img_t *mnf_state_flag(const char *st)
{
    const mnf_state_t *s = mnf_state_find(st);
    return s ? s->flag : NULL;
}

const mnf_img_t *mnf_state_map(const char *st)
{
    const mnf_state_t *s = mnf_state_find(st);
    return s ? s->map : NULL;
}

const char *mnf_state_name(const char *st)
{
    const mnf_state_t *s = mnf_state_find(st);
    return s ? s->name : NULL;
}

bool mnf_state_has_both(const char *st)
{
    const mnf_state_t *s = mnf_state_find(st);
    return s != NULL && s->flag != NULL && s->map != NULL;
}

/* ------------------------------------------------------------------------
 * ASL fingerspelling
 * ---------------------------------------------------------------------- */

size_t mnf_sign_count(void)
{
    return (size_t)mnf_sign_count_val;
}

const mnf_sign_t *mnf_sign_at(size_t index)
{
    if (index >= (size_t)mnf_sign_count_val) return NULL;
    return &mnf_sign_table[index];
}

const mnf_sign_t *mnf_sign_find(char letter)
{
    /* The table is A to Z with no gaps, so a letter is its own index. */
    const int up = toupper((unsigned char)letter);
    if (up < 'A' || up > 'Z') return NULL;
    return mnf_sign_at((size_t)(up - 'A'));
}

const mnf_img_t *mnf_sign(char letter)
{
    const mnf_sign_t *s = mnf_sign_find(letter);
    return s ? s->img : NULL;
}

/* ------------------------------------------------------------------------
 * Pixel access
 * ---------------------------------------------------------------------- */

uint16_t mnf_rgb565(uint8_t r, uint8_t g, uint8_t b)
{
    return (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
}

uint8_t mnf_index_at(const mnf_img_t *img, uint16_t x, uint16_t y)
{
    if (img == NULL || x >= img->w || y >= img->h) return 0;

    const uint8_t *row = img->data + MNF_PALETTE_BYTES + (size_t)MNF_STRIDE(img->w) * y;
    const uint8_t byte = row[x >> 1];
    /* Leftmost pixel of each pair is the high nibble. */
    return (x & 1) ? (byte & 0x0F) : (byte >> 4);
}

uint32_t mnf_palette_argb(const mnf_img_t *img, uint8_t index)
{
    if (img == NULL || index >= MNF_PALETTE_ENTRIES) return 0;

    const uint8_t *e = img->data + (size_t)index * 4;   /* B, G, R, A */
    return ((uint32_t)e[3] << 24) | ((uint32_t)e[2] << 16) |
           ((uint32_t)e[1] << 8)  | (uint32_t)e[0];
}

uint32_t mnf_pixel_argb(const mnf_img_t *img, uint16_t x, uint16_t y)
{
    if (img == NULL || x >= img->w || y >= img->h) return 0;
    return mnf_palette_argb(img, mnf_index_at(img, x, y));
}

/* Split RGB565 back into 8-bit components for blending. */
static void unpack565(uint16_t c, uint8_t *r, uint8_t *g, uint8_t *b)
{
    *r = (uint8_t)(((c >> 11) & 0x1F) * 255 / 31);
    *g = (uint8_t)(((c >> 5) & 0x3F) * 255 / 63);
    *b = (uint8_t)((c & 0x1F) * 255 / 31);
}

void mnf_row_rgb565(const mnf_img_t *img, uint16_t y, uint16_t *out, uint16_t bg565)
{
    if (img == NULL || out == NULL || y >= img->h) return;

    uint8_t br, bg, bb;
    unpack565(bg565, &br, &bg, &bb);

    /* Composite the 16 palette entries once per row rather than per pixel. */
    uint16_t lut[MNF_PALETTE_ENTRIES];
    for (uint8_t i = 0; i < MNF_PALETTE_ENTRIES; i++) {
        const uint8_t *e = img->data + (size_t)i * 4;   /* B, G, R, A */
        const uint16_t a = e[3];
        if (a == 255) {
            lut[i] = mnf_rgb565(e[2], e[1], e[0]);
        } else if (a == 0) {
            lut[i] = bg565;
        } else {
            const uint16_t ia = 255 - a;
            lut[i] = mnf_rgb565((uint8_t)((e[2] * a + br * ia) / 255),
                                (uint8_t)((e[1] * a + bg * ia) / 255),
                                (uint8_t)((e[0] * a + bb * ia) / 255));
        }
    }

    const uint8_t *row = img->data + MNF_PALETTE_BYTES + (size_t)MNF_STRIDE(img->w) * y;
    for (uint16_t x = 0; x < img->w; x++) {
        const uint8_t byte = row[x >> 1];
        out[x] = lut[(x & 1) ? (byte & 0x0F) : (byte >> 4)];
    }
}

void mnf_row_rgb565_tint(const mnf_img_t *img, uint16_t y, uint16_t *out,
                         uint16_t bg565, uint16_t fg565)
{
    if (img == NULL || out == NULL || y >= img->h) return;

    uint8_t br, bg, bb, fr, fg, fb;
    unpack565(bg565, &br, &bg, &bb);
    unpack565(fg565, &fr, &fg, &fb);

    /* Alpha comes from the palette entry; colour is ignored. For map
     * silhouettes the palette is an alpha ramp, so index == alpha level. */
    uint16_t lut[MNF_PALETTE_ENTRIES];
    for (uint8_t i = 0; i < MNF_PALETTE_ENTRIES; i++) {
        const uint16_t a = img->data[(size_t)i * 4 + 3];
        const uint16_t ia = 255 - a;
        lut[i] = mnf_rgb565((uint8_t)((fr * a + br * ia) / 255),
                            (uint8_t)((fg * a + bg * ia) / 255),
                            (uint8_t)((fb * a + bb * ia) / 255));
    }

    const uint8_t *row = img->data + MNF_PALETTE_BYTES + (size_t)MNF_STRIDE(img->w) * y;
    for (uint16_t x = 0; x < img->w; x++) {
        const uint8_t byte = row[x >> 1];
        out[x] = lut[(x & 1) ? (byte & 0x0F) : (byte >> 4)];
    }
}
'''
